import unittest

import emailnorm


class EmailTests(unittest.TestCase):
    def test_lowercases_address(self):
        self.assertEqual(
            emailnorm.normalize_email("Ada@Example.COM"),
            "ada@example.com",
        )


if __name__ == "__main__":
    unittest.main()

